func (t TrackingEvent) Discriminator() (string, error) {
	var discriminator struct {
		Discriminator string `json:"event_type"`
	}
	err := json.Unmarshal(t.union, &discriminator)
	return discriminator.Discriminator, err
}

func (t TrackingEvent) ValueByDiscriminator() (interface{}, error) {
	discriminator, err := t.Discriminator()
	if err != nil {
		return nil, err
	}
	switch discriminator {
	case "exercise.answer_sent":
		return t.AsExerciseAnswerSentEvent()
	case "exercise.ended":
		return t.AsExerciseEndedEvent()
	case "exercise.progress":
		return t.AsExerciseProgressEvent()
	case "exercise.started":
		return t.AsExerciseStartedEvent()
	case "lesson.completed":
		return t.AsLessonCompletedEvent()
	case "lesson.resumed":
		return t.AsLessonResumedEvent()
	case "lesson.started":
		return t.AsLessonStartedEvent()
	default:
		return nil, errors.New("unknown discriminator value: " + discriminator)
	}
}

